    if(size<3) return 0;

    leptSetStdNullHandler();

    PIX *pixs1, *pixs2, *pix1;

    pixs1 = pixReadMemSpix(data, size);
    if(pixs1==NULL) return 0;
    pixs2 = pixReadMemSpix(&data[1], size);
    if(pixs2==NULL){
        pixDestroy(&pixs1);
        return 0;
